def fibonacci_dynamic(n): 
    # Check if the number was already processed
    if n in fibonacci_cache: 
        return fibonacci_cache[n] 

    # Compute the Nth term 
    if n == 1: 
        value = 1
    elif n == 2: 
        value = 1
    elif n > 2: 
