class Vector3D:
    def __init__(self, x=0, y=0, z=0):
        self.x = x
        self.y = y
        self.z = z

    def add(self, vector):
        x = self.x + vector.x
        y = self.y + vector.y
        z = self.z + vector.z
        return Vector3D(x,y,z)

    def subtract(self, vector):
        x = self.x - vector.x
        y = self.y - vector.y
        z = self.z - vector.z
